import{_ as t,c as s,o as a,ag as n}from"./chunks/framework.DfL_BkQ-.js";const b=JSON.parse('{"title":"Экономика","description":"","frontmatter":{},"headers":[],"relativePath":"info/economy.md","filePath":"info/economy.md"}'),e={name:"info/economy.md"};function r(p,o,c,l,g,i){return a(),s("div",null,[...o[0]||(o[0]=[n('<h1 id="экономика" tabindex="-1">Экономика <a class="header-anchor" href="#экономика" aria-label="Permalink to &quot;Экономика&quot;">​</a></h1><h2 id="▌-валюты-и-заработок" tabindex="-1">▌ Валюты и заработок <a class="header-anchor" href="#▌-валюты-и-заработок" aria-label="Permalink to &quot;▌ Валюты и заработок&quot;">​</a></h2><p><strong>Валюты:</strong></p><blockquote><p>▪ <span style="color:#fbbf24;"><strong>Ⓜ</strong></span> — <span style="color:#fbbf24;"><strong>Монеты</strong></span> Основная валюта, которая используется везде, кроме премиум торговца.</p><p>▪ <span style="color:#a855f7;"><strong>Ⓟ</strong></span> — <span style="color:#a855f7;"><strong>Пексы</strong></span> Премиум валюта, которая используется у премиум торговца и сундучника.</p></blockquote><p><strong>Заработок:</strong></p><blockquote><p>▪ Каждые <strong>10</strong> минут ты получаешь <span style="color:#fbbf24;"><strong>10Ⓜ</strong></span></p><p>▪ <strong>Аукцион</strong> — верный способ заработать <span style="color:#fbbf24;"><strong>монеты</strong></span></p><p>▪ <strong>Личные магазины</strong> — отличная альтернатива аукциону</p><p>▪ Скупщик хорошо заплатит за нужные ему ресурсы</p><p>▪ Ивенты и розыгрыши помогут пополнить кошелёк</p><p>▪ Помогай серверу пожертвованием и получай <span style="color:#a855f7;"><strong>пексы</strong></span></p></blockquote><h2 id="▌-игровои-аукцион" tabindex="-1">▌ Игровой аукцион <a class="header-anchor" href="#▌-игровои-аукцион" aria-label="Permalink to &quot;▌ Игровой аукцион&quot;">​</a></h2><p><strong>Аукцион</strong> — основной способ заработка большого количества монет. Каждый игрок может пользоваться аукционом для покупки или продажи ресурсов.</p><blockquote><p>▪ <code>/ah</code> — Открыть интерфейс аукциона</p><p>▪ <code>/ah sell &lt;цена&gt;</code> — Выставить предмет</p><p>▪ <code>/ah expired</code> — Интерфейс истёкших предметов</p><p>▪ <code>/minimal</code> — Минимальные цены</p></blockquote><p><strong>Однако!</strong> Обычный игрок имеет всего <strong>5</strong> слотов для предметов на площадке. Чем выше привилегия, тем слотов больше.</p><div class="warning custom-block"><p class="custom-block-title">Внимание</p><p>Не нарушай <a href="/rules/">правила</a> аукциона при его использовании!</p></div><h2 id="▌-личные-магазины" tabindex="-1">▌ Личные магазины <a class="header-anchor" href="#▌-личные-магазины" aria-label="Permalink to &quot;▌ Личные магазины&quot;">​</a></h2><p><strong>Магазины</strong> — уникальная механика, которая позволяет игрокам создавать личные торговые лавки и точки телепорта к ним.</p><blockquote><p>▪ <code>/cshop help</code> — Помощь по командам</p><p>▪ <code>/cshop browse</code> — Каталог магазинов игроков</p></blockquote><p><strong>Важно:</strong> Для создания таких магазинов необходима привилегия <span style="color:#a855f7;"><strong>ʜᴇʀᴏɪᴄ</strong></span> и выше. Стоимость создания магазина: <span style="color:#fbbf24;"><strong>250Ⓜ</strong></span>.</p><div class="info custom-block"><p class="custom-block-title">Гайд</p><p>Подробный гайд по созданию магазинов можно будет найти в разделе гайдов.</p></div>',16)])])}const f=t(e,[["render",r]]);export{b as __pageData,f as default};
